{"code":"import pandas as pd
import json

def processing(dfs):
    df = dfs[0]

    def parse_details(row):
        try:
            data = json.loads(row)
            shipping = data.get('shipping', {})
            method = shipping.get('method')
            cost = shipping.get('cost')
            return pd.Series({'method': method, 'cost': float(cost) if cost is not None else None})
