{"code":"import pandas as pd
import ast

# Mocking dfs[0] to test the parsing
data = {
    'details': [
        "{'shipping': {'method': 'express', 'cost': '12.99'}}",
        "{'shipping': {'method': 'express', 'cost': '14.99'}}",
        "{'shipping': {'method': 'standard', 'cost': '6.49'}}"
    ]
}
dfs = [pd.DataFrame(data)]

def processing(dfs):
    orders = dfs[0]

    def parse_details(details_str):
        try:
            return ast.literal_eval(details_str)
        except:
            return {}

    orders['details_parsed'] = orders['details'].apply(parse_details)

    def get_shipping_info(details_dict):
        shipping = details_dict.get('shipping', {})
        # Ensure cost is a float
        cost = shipping.get('cost')
        try:
            cost = float(cost)
        except:
            cost = 0.0
        return shipping.get('method'), cost

    temp = orders['details_parsed'].apply(lambda x: pd.Series(get_shipping_info(x)))
    orders['shipping_method'] = temp[0]
    orders['shipping_cost'] = temp[1]

    # Filter for express
    express_orders = orders[orders['shipping_method'] == 'express']

    # Calculate average
    avg_cost = express_orders['shipping_cost'].mean()

    return pd.DataFrame({'average_shipping_cost': [round(avg_cost, 2)]})

print(processing(dfs))
"}

